def factorial(n: int) -> int:
    if n <= 1:  # base case
        return 1
    return n * factorial(n - 1)  # recursive case on n - 1


def sum_digits(n: int) -> int:
    if n < 10:  # one digit left
        return n
    return n % 10 + sum_digits(n // 10)


def trace(n: int, depth: int = 0) -> None:
    pad = "  " * depth
    if n == 0:
        print(f"{pad}base case")
        return
    print(f"{pad}call {n}")
    trace(n - 1, depth + 1)
    print(f"{pad}back in {n}")


for n in [0, 5, 20]:
    print(f"{n}! = {factorial(n)}")
for n in [7, 9045]:
    print(f"sum_digits({n}) = {sum_digits(n)}")
trace(3)

