import functools

calls = 0


def fib_plain(n: int) -> int:
    global calls
    calls += 1
    if n < 2:
        return n
    return fib_plain(n - 1) + fib_plain(n - 2)


@functools.cache
def fib_cached(n: int) -> int:
    if n < 2:
        return n
    return fib_cached(n - 1) + fib_cached(n - 2)


def fib_memo(n: int, memo: dict[int, int]) -> int:
    if n < 2:
        return n
    if n not in memo:
        memo[n] = fib_memo(n - 1, memo) + fib_memo(n - 2, memo)
    return memo[n]


print(f"plain: fib(25) = {fib_plain(25)} in {calls:,} calls")
print(f"cache: fib(90) = {fib_cached(90)}")
memo = {}
print(f"memo:  fib(90) = {fib_memo(90, memo)} with {len(memo)} saved answers")

