DIRECTIONS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def dfs(grid: list[str], visited: set, r: int, c: int) -> int:
    if not (0 <= r < len(grid) and 0 <= c < len(grid[0])):
        return 0  # off the grid
    if grid[r][c] != "#" or (r, c) in visited:
        return 0  # water or already visited
    visited.add((r, c))
    size = 1
    for dr, dc in DIRECTIONS:
        size += dfs(grid, visited, r + dr, c + dc)
    return size


grid = [
    "##..#",
    "#...#",
    "..#..",
    ".###.",
    "#...#",
]
visited = set()
sizes = []
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] == "#" and (r, c) not in visited:
            sizes.append(dfs(grid, visited, r, c))
print(f"Islands: {len(sizes)}")
print("Sizes:", *sizes)

