import sys

sys.setrecursionlimit(5_000)
DIRECTIONS = [(-1, 0), (1, 0), (0, -1), (0, 1)]


def dfs(grid: list[str], visited: set, r: int, c: int) -> int:
    if not (0 <= r < len(grid) and 0 <= c < len(grid[0])):
        return 0
    if grid[r][c] != "#" or (r, c) in visited:
        return 0
    visited.add((r, c))
    size = 1
    for dr, dc in DIRECTIONS:
        size += dfs(grid, visited, r + dr, c + dc)
    return size


grid = [line.strip() for line in sys.stdin if line.strip()]
visited = set()
sizes = []
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] == "#" and (r, c) not in visited:
            sizes.append(dfs(grid, visited, r, c))
print(f"Largest island: {max(sizes, default=0)}")
